_KG_CACHE_DIR = str(Path(__file__).resolve().parents[2] / ".kg_cache")

# Set up logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)


class BaseNERScorer:
    """
    Base class for NER scorers containing shared functionality.
    Provides common methods for entity extraction and DBpedia mapping.
    """
    
    def __init__(self, spacy_model: str = "en_core_web_sm"):
        """
        Initialize the base NER scorer.
        
        Args:
            spacy_model: Name of the spaCy model to use
        """
        # try:
        #     self.nlp = spacy.load(spacy_model)
        #     logger.info("Loaded spaCy model: %s", spacy_model)
        # except IOError:
        #     logger.error("Could not load spaCy model: %s", spacy_model)
        #     raise

        if NLP_MODEL is None:
            raise ValueError("spaCy model not available. Check the configuration.")
        self.nlp = NLP_MODEL
        logger.info("BaseNERScorer initialized with shared spaCy model")
        
        # Define mappings between DBpedia ontology classes and standard NER labels
        self.dbpedia_to_ner_mapping = {
            # Person related
            "http://dbpedia.org/ontology/Person": "PERSON",
            "http://dbpedia.org/ontology/Politician": "PERSON",
            "http://dbpedia.org/ontology/Actor": "PERSON",
            "http://dbpedia.org/ontology/Athlete": "PERSON",
            "http://dbpedia.org/ontology/Writer": "PERSON",
            "http://dbpedia.org/ontology/Scientist": "PERSON",
            
            # Organization related
            "http://dbpedia.org/ontology/Organisation": "ORG",
            "http://dbpedia.org/ontology/Company": "ORG",
            "http://dbpedia.org/ontology/GovernmentAgency": "ORG",
            "http://dbpedia.org/ontology/MilitaryUnit": "ORG",
            "http://dbpedia.org/ontology/PoliticalParty": "ORG",
            "http://dbpedia.org/ontology/University": "ORG",
            "http://dbpedia.org/ontology/School": "ORG",
            
            # Location related
            "http://dbpedia.org/ontology/Place": "GPE",
            "http://dbpedia.org/ontology/Country": "GPE",
            "http://dbpedia.org/ontology/City": "GPE",
            "http://dbpedia.org/ontology/State": "GPE",
            "http://dbpedia.org/ontology/County": "GPE",
            "http://dbpedia.org/ontology/River": "LOC",
            "http://dbpedia.org/ontology/Mountain": "LOC",
            "http://dbpedia.org/ontology/Lake": "LOC",
            
            # Money and quantities
            "http://dbpedia.org/ontology/Currency": "MONEY",
            
            # Events
            "http://dbpedia.org/ontology/Event": "EVENT",
            "http://dbpedia.org/ontology/SportsEvent": "EVENT",
            "http://dbpedia.org/ontology/MilitaryConflict": "EVENT",
            
            # Products and works
            "http://dbpedia.org/ontology/Work": "WORK_OF_ART",
            "http://dbpedia.org/ontology/Book": "WORK_OF_ART",
            "http://dbpedia.org/ontology/Film": "WORK_OF_ART",
            "http://dbpedia.org/ontology/Song": "WORK_OF_ART",
            
            # Miscellaneous
            "http://dbpedia.org/ontology/Language": "LANGUAGE",
        }
        
        # Reverse mapping for quick lookup
        self.ner_to_dbpedia_mapping = defaultdict(list)
        for dbpedia_class, ner_label in self.dbpedia_to_ner_mapping.items():
            self.ner_to_dbpedia_mapping[ner_label].append(dbpedia_class)

    def extract_entities_from_triplets(self, triples: List[Tuple[str, str, str]]) -> List[NEREntity]:
        """
        Extract entities from RDF triplets generated by LLMs.
        
        Args:
            triples: List of (subject, predicate, object) tuples
            
        Returns:
            List of NEREntity objects extracted from triplets
        """
        entities = []
        entity_types = {}  # Map entity URI to its type
        entity_names = {}  # Map entity URI to its human-readable name
        
        # First pass: collect entity types and names
        for subject, predicate, obj in triples:
            # Check for rdf:type relations to determine entity types
            if "type" in predicate.lower():
                if obj in self.dbpedia_to_ner_mapping:
                    entity_types[subject] = self.dbpedia_to_ner_mapping[obj]
            
            # Check for foaf:name or similar properties to get human-readable names
            if any(prop in predicate.lower() for prop in ["name", "foaf:name", "rdfs:label"]):
                # Clean the object (remove quotes, language tags, etc.)
                clean_name = self._clean_literal_value(obj)
                if clean_name:
                    entity_names[subject] = clean_name
        
        # Second pass: create NEREntity objects
        for entity_uri, entity_type in entity_types.items():
            entity_name = entity_names.get(entity_uri, self._extract_name_from_uri(entity_uri))
            
            if entity_name:
                entities.append(NEREntity(
                    text=entity_name,
                    label=entity_type,
                    start=0,  # We don't have position info from triplets
                    end=len(entity_name),
                    confidence=0.9,  # High confidence for rule-based extraction
                    source="rule_based"
                ))
        
        return entities

    def _clean_literal_value(self, literal: str) -> str:
        """Clean literal values from RDF triples (remove quotes, language tags, etc.)"""
        if not literal:
            return ""
        
        # Remove quotes and language tags
        cleaned = literal.strip()
        if cleaned.startswith('"') and '"' in cleaned[1:]:
            # Find the closing quote
            end_quote = cleaned.rfind('"')
            if end_quote > 0:
                cleaned = cleaned[1:end_quote]
        
        # Remove any remaining language tags or datatype markers
        if '@' in cleaned:
            cleaned = cleaned.split('@')[0]
        if '^^' in cleaned:
            cleaned = cleaned.split('^^')[0]
        
        return cleaned.strip()
    
    def _extract_name_from_uri(self, uri: str) -> str:
        """Extract human-readable name from DBpedia URI"""
        if not uri:
            return ""
        
        # Extract the last part of the URI after the last /
        name_part = uri.split('/')[-1]
        
        # Replace underscores with spaces
        name_part = name_part.replace('_', ' ')
        
        # Remove common prefixes/suffixes
        name_part = re.sub(r'^(http://dbpedia\.org/resource/)', '', name_part)
        
        return name_part.strip()


class NERConsistencyScorer(BaseNERScorer):
    """
    Class for calculating NER consistency scores between rule-based extraction (from triplets)
    and spaCy NER results.
    
    Uses F1 score (harmonic mean of precision and recall) as the primary consistency metric.
    This is the standard evaluation metric used in NER research (CoNLL, ACE, etc.).
    
    The scoring methodology:
    - Calculates True Positives (TP): entities that match in both text and label
    - Calculates False Positives (FP): entities in spaCy but not in rule-based
    - Calculates False Negatives (FN): entities in rule-based but not in spaCy
    - F1 = 2 * (Precision * Recall) / (Precision + Recall)
    
    Optional confidence-weighted scoring is available to weight inconsistencies by
    confidence scores for more nuanced evaluation.
    """
    
    def __init__(self, spacy_model: str = "en_core_web_sm"):
        """
        Initialize the NER consistency scorer.
        
        Args:
            spacy_model: Name of the spaCy model to use
        """
        super().__init__(spacy_model)

    def _calculate_entity_overlap(self, 
                                 rule_based_entities: List[NEREntity], 
                                 spacy_entities: List[NEREntity]) -> Tuple[int, int, int]:
        """
        Calculate entity overlap between rule-based and spaCy entities.
        Uses exact matching on (text, label) pairs.
        
        Args:
            rule_based_entities: Entities extracted from triplets
            spacy_entities: Entities extracted by spaCy
            
        Returns:
            Tuple of (true_positives, false_positives, false_negatives)
            - True Positives: entities that match in both text and label
            - False Positives: entities in spaCy but not in rule-based
            - False Negatives: entities in rule-based but not in spaCy
        """
        # Convert to sets of (text, label) tuples for comparison
        # Use lowercase text for case-insensitive matching
        rule_set = {(e.text.lower(), e.label) for e in rule_based_entities}
        spacy_set = {(e.text.lower(), e.label) for e in spacy_entities}
        
        # True Positives: entities that match in both text and label
        true_positives = len(rule_set & spacy_set)
        
        # False Positives: entities in spaCy but not in rule-based
        false_positives = len(spacy_set - rule_set)
        
        # False Negatives: entities in rule-based but not in spaCy
        false_negatives = len(rule_set - spacy_set)
        
        return true_positives, false_positives, false_negatives

    def calculate_consistency_score(self, news_text: str, triples: List[Tuple[str, str, str]], use_confidence_weighting: bool = False) -> float:
        """
        Calculate NER consistency score between rule-based and spaCy extraction.
        
        Uses F1 score (harmonic mean of precision and recall) as the consistency metric.
        This is the standard evaluation metric used in NER research (CoNLL, ACE, etc.).
        
        Formula:
        - Precision = TP / (TP + FP)
        - Recall = TP / (TP + FN)
        - F1 = 2 * (Precision * Recall) / (Precision + Recall)
        
        Where:
        - TP (True Positives): entities that match in both text and label
        - FP (False Positives): entities in spaCy but not in rule-based
        - FN (False Negatives): entities in rule-based but not in spaCy
        
        Args:
            news_text: Original news text
            triples: Generated RDF triples
            use_confidence_weighting: If True, weight inconsistencies by confidence scores.
                                     When enabled, conflicting labels are weighted by confidence
                                     difference, and missing entities are weighted by source confidence.
            
        Returns:
            Consistency score (0-1, higher is better). Returns F1 score.
        """
        try:
            # Extract entities using both methods
            rule_based_entities = self.extract_entities_from_triplets(triples)
            spacy_entities = self.extract_entities_with_spacy(news_text)
            
            if use_confidence_weighting:
                return self._calculate_confidence_weighted_score(rule_based_entities, spacy_entities, news_text)
            
            # Calculate entity overlap metrics
            true_positives, false_positives, false_negatives = self._calculate_entity_overlap(
                rule_based_entities, spacy_entities
            )
            
            # Calculate Precision and Recall
            precision = true_positives / (true_positives + false_positives) if (true_positives + false_positives) > 0 else 0.0
            recall = true_positives / (true_positives + false_negatives) if (true_positives + false_negatives) > 0 else 0.0
            
            # Calculate F1 Score (harmonic mean of precision and recall)
            if precision + recall > 0:
                f1_score = 2 * (precision * recall) / (precision + recall)
            else:
                f1_score = 0.0
            
            return min(max(f1_score, 0.0), 1.0)  # Ensure score is between 0 and 1
            
        except Exception as e:
            logger.error("Error calculating NER consistency score: %s", str(e))
            return -1

    def _calculate_confidence_weighted_score(self, 
                                             rule_based_entities: List[NEREntity], 
                                             spacy_entities: List[NEREntity],
                                             news_text: str) -> float:
        """
        Calculate confidence-weighted consistency score.
        
        Args:
            rule_based_entities: Entities extracted from triplets
            spacy_entities: Entities extracted by spaCy
            news_text: Original text for context
            
        Returns:
            Weighted F1 score (0-1, higher is better)
        """
        # Find inconsistencies with confidence information
        inconsistencies = self.find_ner_inconsistencies(rule_based_entities, spacy_entities, news_text)
        
        # Calculate base entity overlap
        true_positives, false_positives, false_negatives = self._calculate_entity_overlap(
            rule_based_entities, spacy_entities
        )
        
        # Weight inconsistencies by confidence
        weighted_fp = 0.0
        weighted_fn = 0.0
        
        for inc in inconsistencies:
            if inc.inconsistency_type == "conflicting":
                # Weight by confidence difference (higher difference = more significant conflict)
                conf_diff = abs(inc.rule_based_confidence - inc.spacy_confidence)
                weight = 1.0 + conf_diff
                # This conflict contributes to both FP and FN
                weighted_fp += weight * 0.5
                weighted_fn += weight * 0.5
            elif inc.inconsistency_type == "missing_in_spacy":
                # Weight by rule-based confidence (higher confidence = more significant miss)
                weighted_fn += inc.rule_based_confidence
            elif inc.inconsistency_type == "missing_in_rule_based":
                # Weight by spaCy confidence (higher confidence = more significant miss)
                weighted_fp += inc.spacy_confidence
        
        # Calculate weighted precision and recall
        weighted_precision = true_positives / (true_positives + weighted_fp) if (true_positives + weighted_fp) > 0 else 0.0
        weighted_recall = true_positives / (true_positives + weighted_fn) if (true_positives + weighted_fn) > 0 else 0.0
        
        # Calculate weighted F1 score
        if weighted_precision + weighted_recall > 0:
            weighted_f1 = 2 * (weighted_precision * weighted_recall) / (weighted_precision + weighted_recall)
        else:
            weighted_f1 = 0.0
        
        return min(max(weighted_f1, 0.0), 1.0)

    def get_detailed_consistency_analysis(self, news_text: str, triples: List[Tuple[str, str, str]]) -> Dict:
        """
        Get detailed NER consistency analysis.
        
        Args:
            news_text: Original news text
            triples: Generated RDF triples
            
        Returns:
            Dictionary containing detailed consistency analysis including:
            - consistency_score: F1 score (0-1, higher is better)
            - rule_based_entities: List of entities extracted from triplets
            - spacy_entities: List of entities extracted by spaCy
            - inconsistencies: List of detected inconsistencies
            - statistics: Detailed metrics including precision, recall, F1, TP/FP/FN counts
        """
        # Extract entities using both methods
        rule_based_entities = self.extract_entities_from_triplets(triples)
        spacy_entities = self.extract_entities_with_spacy(news_text)
        
        # Find inconsistencies
        inconsistencies = self.find_ner_inconsistencies(rule_based_entities, spacy_entities, news_text)
        
        # Calculate entity overlap metrics
        true_positives, false_positives, false_negatives = self._calculate_entity_overlap(
            rule_based_entities, spacy_entities
        )
        
        # Calculate Precision, Recall, and F1
        precision = true_positives / (true_positives + false_positives) if (true_positives + false_positives) > 0 else 0.0
        recall = true_positives / (true_positives + false_negatives) if (true_positives + false_negatives) > 0 else 0.0
        f1_score = 2 * (precision * recall) / (precision + recall) if (precision + recall) > 0 else 0.0
        
        # Get consistency score (F1)
        consistency_score = self.calculate_consistency_score(news_text, triples)
        
        # Calculate basic statistics
        total_rule_based = len(rule_based_entities)
        total_spacy = len(spacy_entities)
        total_inconsistencies = len(inconsistencies)
        
        return {
            "consistency_score": consistency_score,
            "rule_based_entities": [{"text": e.text, "label": e.label, "start": e.start, "end": e.end} for e in rule_based_entities],
            "spacy_entities": [{"text": e.text, "label": e.label, "start": e.start, "end": e.end} for e in spacy_entities],
            "inconsistencies": [{"type": inc.inconsistency_type, "entity_text": inc.entity_text, "rule_label": inc.rule_based_label, "spacy_label": inc.spacy_label, "context": inc.context} for inc in inconsistencies],
            "statistics": {
                "total_rule_based": total_rule_based,
                "total_spacy": total_spacy,
                "total_inconsistencies": total_inconsistencies,
                "true_positives": true_positives,
                "false_positives": false_positives,
                "false_negatives": false_negatives,
                "precision": precision,
                "recall": recall,
                "f1_score": f1_score
            }
        }
    
    def extract_entities_with_spacy(self, text: str) -> List[NEREntity]:
        """
        Extract entities from text using spaCy NER.
        
        Args:
            text: Input text to process
            
        Returns:
            List of NEREntity objects extracted by spaCy
        """
        doc = self.nlp(text)
        entities = []
        
        for ent in doc.ents:
            # Try to get confidence score, default to 0.8 if not available
            confidence = 0.8
            if hasattr(ent._, 'confidence'):
                confidence = float(ent._.confidence)
            
            entities.append(NEREntity(
                text=ent.text,
                label=ent.label_,
                start=ent.start_char,
                end=ent.end_char,
                confidence=confidence,
                source="spacy"
            ))
        
        return entities
    
    def find_ner_inconsistencies(self, 
                                rule_based_entities: List[NEREntity], 
                                spacy_entities: List[NEREntity],
                                text: str = "") -> List[NERInconsistency]:
        """
        Compare rule-based and spaCy entities to find inconsistencies.
        
        Uses exact (text, label) matching for primary comparison and only counts
        true inconsistencies (not compatible label variants). Compatible label
        variants (e.g., PERSON/PER, ORG/ORGANIZATION) are filtered out.
        
        Args:
            rule_based_entities: Entities extracted from triplets
            spacy_entities: Entities extracted by spaCy
            text: Original text for context
            
        Returns:
            List of NERInconsistency objects
        """
        inconsistencies = []
        
        # Create lookup dictionaries for easier comparison
        rule_based_lookup = {entity.text.lower(): entity for entity in rule_based_entities}
        spacy_lookup = {entity.text.lower(): entity for entity in spacy_entities}
        
        # Find entities that exist in both but have different labels
        for entity_text, rule_entity in rule_based_lookup.items():
            if entity_text in spacy_lookup:
                spacy_entity = spacy_lookup[entity_text]
                
                # Check if labels are conflicting
                if not self._are_labels_compatible(rule_entity.label, spacy_entity.label):
                    inconsistencies.append(NERInconsistency(
                        entity_text=entity_text,
                        rule_based_label=rule_entity.label,
                        spacy_label=spacy_entity.label,
                        rule_based_confidence=rule_entity.confidence,
                        spacy_confidence=spacy_entity.confidence,
                        inconsistency_type="conflicting",
                        context=self._get_context(text, entity_text)
                    ))
        
        # Find entities that exist in rule-based but missing in spaCy
        for entity_text, rule_entity in rule_based_lookup.items():
            if entity_text not in spacy_lookup:
                # Check if similar entities exist (fuzzy matching)
                similar_entity = self._find_similar_entity(entity_text, spacy_entities)
                if similar_entity:
                    if not self._are_labels_compatible(rule_entity.label, similar_entity.label):
                        inconsistencies.append(NERInconsistency(
                            entity_text=entity_text,
                            rule_based_label=rule_entity.label,
                            spacy_label=similar_entity.label,
                            rule_based_confidence=rule_entity.confidence,
                            spacy_confidence=similar_entity.confidence,
                            inconsistency_type="conflicting",
                            context=self._get_context(text, entity_text)
                        ))
                else:
                    inconsistencies.append(NERInconsistency(
                        entity_text=entity_text,
                        rule_based_label=rule_entity.label,
                        spacy_label="NONE",
                        rule_based_confidence=rule_entity.confidence,
                        spacy_confidence=0.0,
                        inconsistency_type="missing_in_spacy",
                        context=self._get_context(text, entity_text)
                    ))
        
        # Find entities that exist in spaCy but missing in rule-based
        for entity_text, spacy_entity in spacy_lookup.items():
            if entity_text not in rule_based_lookup:
                # Only report high-confidence spaCy entities that are missing
                if spacy_entity.confidence > 0.7:
                    inconsistencies.append(NERInconsistency(
                        entity_text=entity_text,
                        rule_based_label="NONE",
                        spacy_label=spacy_entity.label,
                        rule_based_confidence=0.0,
                        spacy_confidence=spacy_entity.confidence,
                        inconsistency_type="missing_in_rule_based",
                        context=self._get_context(text, entity_text)
                    ))
        
        return inconsistencies
    
    def _are_labels_compatible(self, label1: str, label2: str) -> bool:
        """Check if two NER labels are compatible (not conflicting)"""
        if label1 == label2:
            return True
        
        # Define compatible label groups
        compatible_groups = [
            {"PERSON", "PER"},  # Person variants
            {"ORG", "ORGANIZATION"},  # Organization variants
            {"GPE", "LOC", "LOCATION"},  # Location variants
            {"MONEY", "MONETARY"},  # Money variants
            {"DATE", "TIME"},  # Temporal variants
        ]
        
        for group in compatible_groups:
            if label1 in group and label2 in group:
                return True
        
        return False
    
    def _find_similar_entity(self, target_text: str, entities: List[NEREntity], threshold: float = 0.8) -> Optional[NEREntity]:
        """Find similar entity using fuzzy string matching"""
        target_lower = target_text.lower()
        
        for entity in entities:
            entity_lower = entity.text.lower()
            
            # Simple similarity check
            if target_lower in entity_lower or entity_lower in target_lower:
                return entity
            
            # Check if they share significant words
            target_words = set(target_lower.split())
            entity_words = set(entity_lower.split())
            
            if target_words and entity_words:
                overlap = len(target_words & entity_words) / len(target_words | entity_words)
                if overlap >= threshold:
                    return entity
        
        return None
    
    def _get_context(self, text: str, entity_text: str, context_window: int = 50) -> str:
        """Get context around an entity in the text"""
        if not text or not entity_text:
            return ""
        
        # Find the entity in the text (case-insensitive)
        text_lower = text.lower()
        entity_lower = entity_text.lower()
        
        pos = text_lower.find(entity_lower)
        if pos == -1:
            return ""
        
        # Get context window around the entity
        start = max(0, pos - context_window)
        end = min(len(text), pos + len(entity_text) + context_window)
        
        context = text[start:end].strip()
        
        # Add ellipsis if truncated
        if start > 0:
            context = "..." + context
        if end < len(text):
            context = context + "..."
        
        return context


class RuleDefinitionScorer(BaseNERScorer):
    """
    KG-aware entity verification scorer for evaluating the correctness of LLM-extracted entities.
    Uses a two-layered approach:
      1) Try ontology type via DBpedia/Wikidata (strongest signal for entity verification)
      2) Try spaCy EntityRuler token rules (robust linguistic patterns)
    
    Note: Regex rules have been removed - validation now uses only KG and EntityRuler
    for more robust, knowledge-based verification.
    """
    
    def __init__(self, spacy_model: str = "en_core_web_sm"):
        """
        Initialize the rule definition scorer.
        
        Args:
            spacy_model: Name of the spaCy model to use
        """
        # super().__init__(spacy_model)
        super().__init__(NLP_MODEL)
        
        # Initialize KG client for entity verification
        try:
            self.kgc = KGClient(cache_dir=_KG_CACHE_DIR)
        except Exception as e:
            logger.warning("Failed to initialize KG client: %s. KG verification will be disabled.", str(e))
            self.kgc = None
        
        # Initialize rule definitions for entity recognition
        self.rule_definitions = self._initialize_rule_definitions()
        
        # Build EntityRuler for token-based pattern matching
        try:
            # Check if the component already exists (e.g., from a previous instance)
            if "kg_entity_ruler" in self.nlp.pipe_names:
                # Component already exists, just get a reference to it
                self.entity_ruler = self.nlp.get_pipe("kg_entity_ruler")
            else:
                # Token-based patterns mirroring common rules
                ruler_patterns = [
                    # PERSON: ProperNoun ProperNoun (with optional middle)
                    {"label": "PERSON", "pattern": [{"POS":"PROPN"}, {"POS":"PROPN"}]},
                    {"label": "PERSON", "pattern": [{"POS":"PROPN"}, {"POS":"PROPN"}, {"POS":"PROPN"}]},
                    # ORG: name + legal suffix
                    {"label": "ORG", "pattern": [{"IS_TITLE": True, "OP":"*"}, {"LOWER":{"IN":["inc","inc.","llc","corp","corp.","corporation","company","co","co."]}}]},
                    # GPE/LOC: simple country/state tokens (fallback pattern)
                    {"label": "GPE", "pattern": [{"IS_TITLE": True, "OP":"+"}]},
                    # MONEY: symbol + number
                    {"label": "MONEY", "pattern": [{"ORTH":{"IN":["$","£","€","¥"]}}, {"LIKE_NUM": True}]},
                    # DATE: common numeric date forms
                    {"label": "DATE", "pattern": [{"LIKE_NUM": True}, {"ORTH":{"IN":["/","-"]}}, {"LIKE_NUM": True}, {"ORTH":{"IN":["/","-"]}}, {"LIKE_NUM": True}]},
                    # PERCENT:
                    {"label": "PERCENT", "pattern": [{"LIKE_NUM": True}, {"ORTH":"%"}]},
                ]
                # Insert BEFORE ML NER so rules can fire first
                # Use modern spaCy API: pass string name instead of component object
                self.nlp.add_pipe("entity_ruler", name="kg_entity_ruler", before="ner", config={"validate": True})
                # Get reference to the added component and add patterns
                self.entity_ruler = self.nlp.get_pipe("kg_entity_ruler")
                self.entity_ruler.add_patterns(ruler_patterns)
        except Exception as e:
            logger.warning("Failed to initialize EntityRuler: %s. EntityRuler verification will be disabled.", str(e))
            self.entity_ruler = None

    def _initialize_rule_definitions(self) -> List[RuleDefinition]:
        """
        Initialize rule definitions for entity recognition.
        Note: Regex rules are removed - validation now uses only KG and EntityRuler.
        Returns empty list as rules are no longer needed.
        
        Returns:
            Empty list (rules are no longer used for validation)
        """
        # Regex rules removed - validation now uses only KG and EntityRuler
        return []

    # ---------------- KG mapping helpers ----------------
    def _map_kg_type_to_ner(self, uri: str) -> Optional[str]:
        """
        Map KG ontology URI to NER label.
        Use BaseNERScorer.dbpedia_to_ner_mapping where possible.
        Heuristics for Wikidata/class URIs if needed.
        """
        if uri in self.dbpedia_to_ner_mapping:
            return self.dbpedia_to_ner_mapping[uri]

        # Lightweight heuristics for WD/other URIs
        u = uri.lower()
        if any(k in u for k in ["person", "human", "politician", "athlete", "writer", "scientist"]):
            return "PERSON"
        if any(k in u for k in ["company", "organisation", "organization", "university", "government", "agency", "incorporated", "corporation"]):
            return "ORG"
        if any(k in u for k in ["country", "city", "state", "province", "place", "river", "mountain", "lake"]):
            return "GPE" if any(k in u for k in ["country","city","state","province","place"]) else "LOC"
        if "currency" in u:
            return "MONEY"
        if "event" in u:
            return "EVENT"
        if any(k in u for k in ["book","film","work","song"]):
            return "WORK_OF_ART"
        return None

    def _kg_match_label(self, surface: str, target_label: str) -> Tuple[bool, Optional[str]]:
        """
        Check if entity surface text matches target label in knowledge graph.
        Return (matches_target, uri) where uri is the strongest matching KG type.
        """
        if not self.kgc:
            return False, None
        
        try:
            types = self.kgc.get_types(surface)
        except Exception:
            types = []

        for t in types:
            mapped = self._map_kg_type_to_ner(t)
            if mapped == target_label:
                return True, t
        return False, types[0] if types else None

    def calculate_rule_definition_score(self, news_text: str, triples_list: List[Tuple[str, str, str]]) -> float:
        """
        Calculate a single score representing the quality of entity verification.
        Uses KG-weighted scoring: KG (0.7) + EntityRuler (0.3)
        This evaluates how well KG and EntityRuler verify the entities extracted by the LLM.
        
        Args:
            news_text: Original text to analyze
            triples_list: Generated RDF triples from LLM
            
        Returns:
            Entity verification quality score (0-1, higher is better)
        """
        try:
            # Validate entities against KG and EntityRuler
            rule_validation_results, metrics = self.validate_rule_definitions_against_triples(news_text, triples_list)
            
            total_rules = len(rule_validation_results)
            if total_rules == 0:
                return 0.0
            
            # Calculate average coverage for each method
            n = total_rules
            kg_cov = sum(metrics.get(r, {}).get("kg_coverage", 0.0) for r in rule_validation_results.keys()) / n
            ruler_cov = sum(metrics.get(r, {}).get("ruler_coverage", 0.0) for r in rule_validation_results.keys()) / n
            
            # KG-weighted scoring for better entity verification
            rule_score = 0.7 * kg_cov + 0.3 * ruler_cov
            
            return min(rule_score, 1.0)  # Ensure score doesn't exceed 1.0
            
        except Exception as e:
            logger.error("Error calculating rule definitions score: %s", str(e))
            return -1

    def get_detailed_rule_analysis(self, news_text: str, triples_list: List[Tuple[str, str, str]]) -> Dict:
        """
        Get detailed analysis of rule definitions performance.
        
        Args:
            news_text: Original text to analyze
            triples_list: Generated RDF triples from LLM
            
        Returns:
            Dictionary containing detailed rule definitions analysis
        """
        rule_validation_results, metrics = self.validate_rule_definitions_against_triples(news_text, triples_list)
        rule_score = self.calculate_rule_definition_score(news_text, triples_list)
        
        # Maintain API compatibility - same structure as before
        return {
            "rule_definition_score": rule_score,
            "rule_validation_results": rule_validation_results,
            "total_rules": len(self.rule_definitions),
            "rules_with_matches": len([r for r in rule_validation_results.values() if r.total_matches > 0]),
            "average_coverage": sum(r.coverage_score for r in rule_validation_results.values()) / max(len(rule_validation_results), 1),
            "average_precision": sum(r.precision_score for r in rule_validation_results.values()) / max(len(rule_validation_results), 1)
        }

    def validate_rule_definitions_against_triples(self, text: str, triples_list: List[Tuple[str, str, str]]) -> Tuple[Dict[str, RuleValidationResult], Dict[str, Dict[str, float]]]:
        """
        Validate entities extracted from generated triples using KG and EntityRuler.
        Groups entities by type and validates each type group.
        This evaluates how well KG and EntityRuler verify the entities that the LLM identified.
        
        Args:
            text: Original text (for context)
            triples_list: Generated RDF triples from LLM
            
        Returns:
            Tuple of:
            - Dictionary mapping entity types to validation results
            - Dictionary mapping entity types to metrics (kg_coverage, ruler_coverage)
        """
        # Extract entities from the generated triples
        llm_entities = self.extract_entities_from_triplets(triples_list)
        
        # Group entities by type
        entities_by_type: Dict[str, List[NEREntity]] = defaultdict(list)
        for entity in llm_entities:
            entities_by_type[entity.label].append(entity)
        
        validation_results = {}
        metrics = {}
        
        # Validate each entity type group
        for entity_type, entities in entities_by_type.items():
            # Create a dummy rule for compatibility with existing validation method
            dummy_rule = RuleDefinition(
                name=f"{entity_type}_validation",
                entity_type=entity_type,
                pattern="",
                description=f"Validation for {entity_type} entities using KG and EntityRuler",
                examples=[],
                confidence=1.0,
                is_regex=False
            )
            result, rule_metrics = self._validate_rule_against_entities(dummy_rule, text, entities)
            validation_results[entity_type] = result
            metrics[entity_type] = rule_metrics
        
        return validation_results, metrics
    
    def _validate_rule_against_entities(self, rule: RuleDefinition, text: str, entities: List[NEREntity]) -> Tuple[RuleValidationResult, Dict[str, float]]:
        """
        Validate entities using KG and EntityRuler only (no regex).
        Validation flow: KG → EntityRuler only
        
        Args:
            rule: Rule definition (used for entity_type and name, but not for regex patterns)
            text: Original text (for context)
            entities: List of entities extracted from triples
            
        Returns:
            Tuple of:
            - RuleValidationResult with match information
            - Dict with metrics: kg_coverage, ruler_coverage
        """
        matches = []
        total = 0
        kg_hits = 0
        ruler_hits = 0

        # Only entities of same target label (by LLM) are checked
        relevant_entities = [e for e in entities if e.label == rule.entity_type]

        # --- KG check per entity text (strongest verification) ---
        for e in relevant_entities:
            surface = e.text.strip()
            ok, uri = self._kg_match_label(surface, rule.entity_type)
            if ok:
                kg_hits += 1
                total += 1
                pos = text.lower().find(surface.lower()) if text else -1
                matches.append({
                    "text": surface,
                    "start": pos if pos >= 0 else -1,
                    "end": (pos + len(surface)) if pos >= 0 else -1,
                    "context": self._get_context_by_position(text, pos, pos+len(surface)) if pos >= 0 else f"KG matched ({uri})",
                    "entity_label": e.label,
                    "match_type": "ontology",
                    "ontology": uri
                })

        # --- EntityRuler pass (on text) for missed entities ---
        if text and self.entity_ruler:
            try:
                doc = self.nlp(text)
                ruler_spans = [span for span in doc.ents if span.label_ == rule.entity_type]
                # Index by lower text for quick hit
                ruler_index = {span.text.lower(): span for span in ruler_spans}
                for e in relevant_entities:
                    k = e.text.strip().lower()
                    if k in ruler_index:
                        # Count only if not already matched by KG (avoid double counting)
                        if not any(m.get("text", "").lower() == k and m.get("match_type") == "ontology" for m in matches):
                            sp = ruler_index[k]
                            ruler_hits += 1
                            total += 1
                            matches.append({
                                "text": sp.text,
                                "start": sp.start_char,
                                "end": sp.end_char,
                                "context": self._get_context_by_position(text, sp.start_char, sp.end_char),
                                "entity_label": rule.entity_type,
                                "match_type": "ruler"
                            })
            except Exception as e:
                logger.warning("Error in EntityRuler validation: %s", str(e))

        # Calculate scores
        num_relevant = len(relevant_entities)
        coverage = min(total / max(num_relevant, 1), 1.0)
        precision = 1.0 if total > 0 else 0.0

        # Calculate metrics for each method (no regex)
        metrics = {
            "kg_coverage": min(kg_hits / max(num_relevant, 1), 1.0),
            "ruler_coverage": min(ruler_hits / max(num_relevant, 1), 1.0),
        }

        return RuleValidationResult(
            rule_name=rule.name,
            entity_type=rule.entity_type,
            matches=matches,
            total_matches=total,
            confidence_score=rule.confidence,
            coverage_score=coverage,
            precision_score=precision
        ), metrics

    def _get_context_by_position(self, text: str, start_pos: int, end_pos: int, context_window: int = 50) -> str:
        """Get context around an entity using position information"""
        if not text or start_pos < 0 or end_pos > len(text):
            return ""
        
        # Get context window around the entity
        start = max(0, start_pos - context_window)
        end = min(len(text), end_pos + context_window)
        
        context = text[start:end].strip()
        
        # Add ellipsis if truncated
        if start > 0:
            context = "..." + context
        if end < len(text):
            context = context + "..."
        
        return context


class NERConsistencyChecker:
    """
    Main class for checking NER consistency between rule-based extraction (from triplets)
    and spaCy NER results. This class combines both NER consistency scoring and rule definition scoring.
    """
    
    def __init__(self, spacy_model: str = "en_core_web_sm"):
        """
        Initialize the NER consistency checker.
        
        Args:
            spacy_model: Name of the spaCy model to use
        """
        # Initialize specialized scorers
        self.consistency_scorer = NERConsistencyScorer(spacy_model)
        self.rule_definition_scorer = RuleDefinitionScorer(spacy_model)
        
        # For backward compatibility, expose main attributes
        self.nlp = self.consistency_scorer.nlp
        self.dbpedia_to_ner_mapping = self.consistency_scorer.dbpedia_to_ner_mapping
        self.ner_to_dbpedia_mapping = self.consistency_scorer.ner_to_dbpedia_mapping
        self.rule_definitions = self.rule_definition_scorer.rule_definitions

    def generate_ner_consistency_report(self, 
                                      news_text: str, 
                                      triples: List[Tuple[str, str, str]]) -> Dict:
        """
        Generate a comprehensive NER consistency report including rule definitions check.
        
        Args:
            news_text: Original news text
            triples: Generated RDF triples
            
        Returns:
            Dictionary containing detailed consistency analysis including rule definitions
        """
        # Get consistency analysis
        consistency_analysis = self.consistency_scorer.get_detailed_consistency_analysis(news_text, triples)
        
        # Get rule definitions analysis  
        rule_analysis = self.rule_definition_scorer.get_detailed_rule_analysis(news_text, triples)
        
        # Combine both analyses
        return {
            **consistency_analysis,
            "rule_definitions_report": rule_analysis["rule_validation_results"],
            "rule_definition_score": rule_analysis["rule_definition_score"]
        }
    
    def calculate_rule_definitions_score(self, news_text: str, triples_list: List[Tuple[str, str, str]]) -> float:
        """
        Calculate a single score representing the quality of rule definitions.
        This evaluates how well our rules capture the entities extracted by the LLM.
        
        Args:
            news_text: Original text to analyze
            triples_list: Generated RDF triples from LLM
            
        Returns:
            Rule definitions quality score (0-1, higher is better)
        """
        return self.rule_definition_scorer.calculate_rule_definition_score(news_text, triples_list)

    # Delegate methods to appropriate scorers for backward compatibility
    def extract_entities_from_triplets(self, triples: List[Tuple[str, str, str]]) -> List[NEREntity]:
        return self.consistency_scorer.extract_entities_from_triplets(triples)
    
    def extract_entities_with_spacy(self, text: str) -> List[NEREntity]:
        return self.consistency_scorer.extract_entities_with_spacy(text)
    
    def find_ner_inconsistencies(self, rule_based_entities: List[NEREntity], 
                                spacy_entities: List[NEREntity], text: str = "") -> List[NERInconsistency]:
        return self.consistency_scorer.find_ner_inconsistencies(rule_based_entities, spacy_entities, text)
    
    def validate_rule_definitions_against_triples(self, text: str, triples_list: List[Tuple[str, str, str]]) -> Dict[str, RuleValidationResult]:
        # Return only the validation results (first element) for backward compatibility
        results, _ = self.rule_definition_scorer.validate_rule_definitions_against_triples(text, triples_list)
        return results

